reference_solutions.brute_python:
def missingNumber(nums):
    n = len(nums)
    for i in range(n + 1):
        if i not in nums:
            return i
    return -1

reference_solutions.optimal_python:
def missingNumber(nums):
    n = len(nums)
    expected = n * (n + 1) // 2
    return expected - sum(nums)

reference_solutions.optimal_java:
public class Solution {
    public int missingNumber(int[] nums) {
        int n = nums.length;
        long expected = (long) n * (n + 1) / 2;
        long actual = 0;
        for (int x : nums) actual += x;
        return (int) (expected - actual);
    }
}

